<template><view class="mg-home" :style="viewportCss"><view class="mg-card"><button class="back" @click="back">← 游戏中心</button><text class="eyebrow">RehabMotion 康复游戏</text><text class="title">地鼠大作战</text><text class="sub">箱式深蹲 · 单人 / 2–5人 PK / 合作</text><view class="modes"><button @click="single">单人训练</button><button class="multi" @click="multi">多人房间</button></view><text class="hint">每位玩家使用自己的 RehabMotion 设备，通过 6 位房间码加入同一局。</text><view class="records"><view class="records-head"><text class="records-title">训练记录</text><button v-if="records.length>3" @click="showAll=!showAll">{{showAll?'收起':'全部记录'}}</button></view><text v-if="!records.length" class="empty">暂无记录</text><view v-for="r in visibleRecords" :key="r.id" class="record" @click="expanded=expanded===r.id?'':r.id"><view class="record-top"><strong>{{r.status==='COMPLETED'?'已完成':'未完成'}}</strong><text>{{dateText(r.result.completedAtMs)}}</text></view><text>有效深蹲 {{r.result.training.left_total_count}} 次 · 闪避 {{r.result.game.dodges}} · 得分 {{r.result.game.score}}</text><view v-if="expanded===r.id" class="detail"><text>最大ROM {{Math.round(r.result.training.max_rom_deg)}}° · 整体完成度 {{Math.round(r.result.training.overall_completion_percent)}}%</text><text>总用时 {{Math.round(r.result.elapsedMs/1000)}}秒 · 有效 {{Math.round(r.result.activeElapsedMs/1000)}}秒</text></view></view></view></view></view></template>
<script lang="ts">import{getViewportLayout,viewportStyle}from'../../game-platform/runtime/viewport';import{returnToGameCenter}from'../../game-platform/runtime/navigation';import{resolveDebugEnabled}from'../../game-platform/runtime/debug-gate';import{loadMoleRecords,saveMoleResult,type MoleRecord}from'./records';import type{MoleTrainingResult}from'../types/result';export default{name:'MoleHome',data(){return{records:[] as MoleRecord[],navigating:false,viewport:getViewportLayout(),showAll:false,expanded:'',debugEnabled:false}},computed:{viewportCss():Record<string,string>{return viewportStyle(this.viewport,'--mg-safe-top')},visibleRecords():MoleRecord[]{return this.showAll?this.records:this.records.slice(0,3)}},onLoad(query:Record<string,string|undefined>){this.debugEnabled=resolveDebugEnabled(query?.debug);this.records=loadMoleRecords()},onShow(){this.navigating=false;this.records=loadMoleRecords()},onResize(){this.viewport=getViewportLayout()},methods:{single(){if(this.navigating)return;this.navigating=true;const ret=encodeURIComponent('/pages-mole-game/home/index');uni.navigateTo({url:`/pages-mole-game/prepare/index?${this.debugEnabled?'debug=1&':''}returnUrl=${ret}`,events:{moleGameResult:(r:MoleTrainingResult)=>{saveMoleResult(r)}},fail:()=>this.navigating=false})},multi(){if(this.navigating)return;this.navigating=true;const ret=encodeURIComponent('/pages-mole-game/home/index');uni.navigateTo({url:`/pages-mole-game/multiplayer/lobby/index?${this.debugEnabled?'debug=1&':''}returnUrl=${ret}`,events:{moleGameResult:(r:MoleTrainingResult)=>saveMoleResult(r),moleGameMultiplayerResult:(r:any)=>saveMoleResult(r.localTraining)},fail:()=>this.navigating=false})},dateText(v:number){const d=new Date(v);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},back(){returnToGameCenter()}}}</script>
<style scoped>.mg-home{box-sizing:border-box;min-height:100vh;padding:calc(var(--mg-safe-top,10px) + 12px) 16px 28px;background:linear-gradient(150deg,#e8f6d5,#fff4c6);font-family:"Microsoft YaHei",sans-serif;color:#405425}.mg-card{box-sizing:border-box;width:min(600px,94vw);margin:auto;padding:24px;border:3px solid #77a73c;border-radius:24px;background:#fff}.back{display:flex;align-items:center;justify-content:center;height:40px;margin:0;padding:0 14px;border:0;border-radius:999px;background:#eef7e5;color:#557733}.eyebrow,.title,.sub,.hint,.records-title,.empty,.record text,.detail text{display:block}.title{font-size:44px;font-weight:900;color:#6d8f27}.sub{margin-top:3px}.modes{display:flex;gap:12px;margin:18px 0}.modes button{display:flex;flex:1;align-items:center;justify-content:center;height:56px;margin:0;padding:0 8px;border:0;border-radius:16px;background:#f1b72d;color:#593c08;font-size:17px;font-weight:900;line-height:1.2;white-space:nowrap}.modes .multi{background:#73a63b;color:#fff}.hint{font-size:13px;color:#72815e}.records{margin-top:18px;border-top:2px solid #dfeccb;padding-top:14px}.records-head,.record-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.records-head button{height:34px;margin:0;padding:0 12px;border:0;border-radius:999px;background:#edf6e5;color:#557733}.records-title{font-size:20px;font-weight:900}.empty{padding:16px;color:#869575}.record{margin-top:9px;padding:11px;border-radius:13px;background:#f5faed}.record text{margin-top:3px;font-size:12px}.record-top>text{margin:0;color:#839078}.detail{margin-top:8px;padding-top:6px;border-top:1px solid #dce8d1;color:#65745c}.mg-home button::after{border:0}@media(max-width:420px){.mg-home{padding-left:10px;padding-right:10px}.mg-card{padding:18px}.title{font-size:36px}.modes{gap:8px}.modes button{font-size:16px}}</style>
